export const USERS_KEY = "revtune_users";
export const BOOKINGS_KEY = "bookings";
export const SESSION_KEY = "revtune_session";
export const SERVICES_KEY = "revtune_services";
export const DATA_EVENT = "revtune:data";

export const readJson = (key, fallback) => {
  try {
    return JSON.parse(localStorage.getItem(key)) ?? fallback;
  } catch {
    return fallback;
  }
};

export const writeJson = (key, value) => {
  localStorage.setItem(key, JSON.stringify(value));
  window.dispatchEvent(new CustomEvent(DATA_EVENT, { detail: { key } }));
};

export const makeId = () =>
  `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
